import { Entity, SkinnedMesh, StandardMaterial, Animator, loadGLTF, quat, POSE_STRIDE } from "../engine/index.js";
import { FLAG } from "./protocol.js";
import { CARRY } from "./data.js";

/**
 * TIDEFALL: players as skinned characters. The raider and its clips are generated by tools/make-models.mjs
 * and read with the engine's glTF loader. Everyone shares one skeleton, one geometry and one material; each
 * has an Animator, an eight-colour palette and a few bone scales.
 *
 * WHO. A player's look comes from their id, so everyone sees the same raider for the same player: a skin
 * tone, a hair colour, a hat (straw sun hat, bandana or captain's cap, each a bone the others are scaled
 * away from), a hairstyle (crop, ponytail, long or none) and maybe a beard. The team colour is the shirt, the
 * scarf, the sack band and the pennant.
 *
 * WHAT IT IS DOING. A clip from the state the client knows this frame (swimming, wading, hanging on the
 * grapple, staggering, in the air, running, carrying something heavy), and one-shot clips on events: the
 * shove, the grapple throw, banking (a celebration) and drowning.
 *
 * ON TOP (the `disney-animation-rule-skill`: secondary action and follow-through, derived from the primary
 * motion, never leading it):
 *   - the body leans into acceleration and banks into turns (from velocity change, eased);
 *   - landing squashes the body at the feet in proportion to the fall speed, then recovers;
 *   - the pennant flaps faster the faster the raider runs, and trails behind turns;
 *   - a ponytail swings, lagging the head;
 *   - the loot sack grows with what is carried (the weight you see is the weight you have).
 * All of it eases in real time and none of it touches the match.
 * @module game/characters
 */

let assets = null;
export async function loadCharacters(base = "assets/models/") {
    if (assets) return assets;
    const asset = await loadGLTF(base + "raider.glb");
    assets = { asset, geometry: asset.geometry("body"), upright: asset.upright };
    return assets;
}
export const charactersReady = () => !!assets;

const SKINS = [[0.95, 0.74, 0.58], [0.8, 0.56, 0.4], [0.6, 0.4, 0.27], [0.4, 0.26, 0.17], [0.98, 0.82, 0.68], [0.7, 0.48, 0.33]];
const HAIRS = [[0.12, 0.08, 0.06], [0.35, 0.2, 0.1], [0.72, 0.5, 0.22], [0.86, 0.8, 0.62], [0.55, 0.15, 0.08], [0.2, 0.2, 0.22]];
/** hat colour by hat kind: straw for the sun hat, a choice for the bandana and the cap */
const HAT_COLORS = [[[0.92, 0.8, 0.5]], [[0.85, 0.2, 0.18], [0.95, 0.95, 0.9], [0.2, 0.35, 0.7]], [[0.12, 0.16, 0.3], [0.9, 0.9, 0.86]]];
const CANVAS = [0.84, 0.78, 0.62], LEATHER = [0.45, 0.28, 0.15], WHITE = [0.98, 0.97, 0.95], INK = [0.08, 0.07, 0.07];

/** a stable small hash of an id, for picking looks */
const pick = (id, salt, n) => { let h = Math.imul(id * 2654435761 + salt * 40503, 1597334677) >>> 0; h = (h ^ (h >>> 15)) >>> 0; return h % n; };

let shared = null;
const material = () => shared || (shared = new StandardMaterial({ palette: new Float32Array(StandardMaterial.PALETTE_SIZE * 3).fill(1), specular: 0.18, shininess: 16, rim: [0.5, 0.45, 0.4], rimPower: 3.5 }));
const ONE_SHOT = { shove: 0.55, hookThrow: 0.4, celebrate: 1.3, drown: 1.8 };

export class Raider {
    /** @param {number[]} color team colour @param {number} id player id: picks the look */
    constructor(color, id) {
        const a = assets, sk = a.asset.skeleton;
        this.animator = new Animator(sk, a.asset.clips);
        this.root = new Entity({ name: "raider" });
        this.root.interpolate = false;
        const mesh = new SkinnedMesh(a.geometry, material(), this.animator);
        const P = (this.palette = new Float32Array(StandardMaterial.PALETTE_SIZE * 3));
        const hat = pick(id, 1, 3), hatColors = HAT_COLORS[hat];
        P.set(SKINS[pick(id, 2, SKINS.length)], 3);
        P.set(HAIRS[pick(id, 3, HAIRS.length)], 6);
        P.set(CANVAS, 9);
        P.set(hatColors[pick(id, 4, hatColors.length)], 12);
        P.set(LEATHER, 15); P.set(WHITE, 18); P.set(INK, 21);
        this.emissive = new Float32Array(3);
        mesh.uniforms = { u_palette: P, u_emissive: this.emissive };
        this.setColor(color);
        this.body = this.root.add(new Entity({ name: "body", mesh, cullRadius: 1.8 }));
        this.body.interpolate = false;
        quat.copy(this.body.rotation, a.upright);

        const ix = (name) => sk.index(name);
        this.bones = { hips: ix("hips"), spine: ix("spine"), chest: ix("chest"), head: ix("head"), pack: ix("pack"), flag: ix("flag"), hairB: ix("hairB") };
        // the look: one hat, one hairstyle (or none under a cap), maybe a beard; the rest scaled away
        const hair = pick(id, 5, 4);
        this.hidden = [];
        ["hatA", "hatB", "hatC"].forEach((n, k) => { if (k !== hat) this.hidden.push(ix(n)); });
        ["hairA", "hairB", "hairC"].forEach((n, k) => { if (k !== hair) this.hidden.push(ix(n)); });
        if (pick(id, 6, 3) !== 0) this.hidden.push(ix("beard"));
        this.look = { hat, hair, beard: !this.hidden.includes(ix("beard")) };

        this.stride = 0;
        this.oneShot = null; this.oneShotLeft = 0;
        // secondary motion state (eased in real time)
        this.lean = 0; this.bank = 0; this.squash = 0; this.flap = 0; this.tail = 0; this.tailV = 0; this.pack = 0.8;
        this.last = null;
        this.animator.play("idle", { fade: 0 });
    }

    setColor(c) { this.palette.set(c, 0); }

    /** Play a one-shot clip over whatever else (shove, hookThrow, celebrate, drown). */
    play(name) { this.oneShot = name; this.oneShotLeft = ONE_SHOT[name] || 0.5; this.animator.play(name, { fade: 0.05, loop: false, restart: true }); }
    shove() { this.play("shove"); }

    /**
     * @param {number} dt
     * @param {{ x: number, y: number, z: number, face: number, flags: number, speed: number, vz: number, weight?: number, wade?: boolean }} s
     * @returns {boolean} true on a frame a foot comes down (for the footstep sound)
     */
    update(dt, s) {
        const f = s.flags, an = this.animator, alive = (f & FLAG.alive) !== 0, ground = (f & FLAG.ground) !== 0;
        // a drowning plays out before the body disappears
        if (!alive && this.oneShot !== "drown") { this.root.visible = false; this.last = null; return false; }
        this.root.visible = true;
        this.root.setPosition(s.x, s.y, s.z);
        this.root.setYaw(s.face - Math.PI / 2);
        const weight = s.weight ?? 0, heavy = weight >= 7;

        // ---- the clip
        let step = false;
        if (this.oneShot && (this.oneShotLeft -= dt) <= 0) this.oneShot = null;
        if (!this.oneShot) {
            if (f & FLAG.stun) an.play("stagger", { fade: 0.08 });
            else if (f & FLAG.hook) an.play("hook", { fade: 0.12 });
            else if (f & FLAG.swim) an.play(s.speed > 0.5 ? "swim" : "tread", { fade: 0.25, speed: s.speed > 0.5 ? Math.max(0.6, s.speed / 2.4) : 1 });
            else if (!ground) an.play(s.vz > 0 ? "jump" : "fall", { fade: 0.15 });
            else if (s.wade || (f & FLAG.sunk)) an.play(s.speed > 0.3 ? "wade" : "idle", { fade: 0.2, speed: Math.max(0.5, s.speed / 3) });
            else if (heavy && s.speed > 0.5) an.play("carry", { fade: 0.2, speed: Math.max(0.6, s.speed / 4.2) });
            else if (s.speed > 4.6) an.play("run", { fade: 0.15, speed: s.speed / 8 });
            else if (s.speed > 0.5) an.play("walk", { fade: 0.15, speed: s.speed / 3.4 });
            else an.play("idle", { fade: 0.3 });
        }
        if (ground && !(f & FLAG.swim) && s.speed > 0.5) { this.stride += s.speed * dt; if (this.stride > (heavy ? 1.5 : 1.9)) { this.stride = 0; step = true; } }

        // ---- secondary motion, from how the primary motion changed since last frame
        const k = (rate) => 1 - Math.exp(-dt * rate);
        let accel = 0, turn = 0, landing = 0;
        if (this.last && dt > 0) {
            accel = (s.speed - this.last.speed) / dt;
            let df = s.face - this.last.face;
            if (df > Math.PI) df -= Math.PI * 2; else if (df < -Math.PI) df += Math.PI * 2;
            turn = df / dt;
            if (ground && !this.last.ground && this.last.vz < -5) landing = Math.min(1, (-this.last.vz - 5) / 12);
        }
        this.last = { speed: s.speed, face: s.face, ground, vz: s.vz };
        const swimming = (f & FLAG.swim) !== 0;
        this.lean += ((swimming ? 0 : Math.max(-0.25, Math.min(0.25, accel * 0.02))) - this.lean) * k(6);
        this.bank += ((swimming ? 0 : Math.max(-0.3, Math.min(0.3, -turn * s.speed * 0.012))) - this.bank) * k(5);
        if (landing > this.squash) this.squash = landing;
        this.squash *= Math.exp(-dt * 7);
        this.flap += dt * (3 + s.speed * 1.6);
        // the ponytail: a spring that the head's turning and the body's acceleration push
        this.tailV += (-this.tail * 60 - this.tailV * 7 + turn * 3 - accel * 0.6) * dt;
        this.tail += this.tailV * dt;
        this.tail = Math.max(-0.9, Math.min(0.9, this.tail));
        // the sack: bigger the more is in it
        this.pack += ((0.8 + Math.min(1, weight / CARRY.maxWeight) * 0.5) - this.pack) * k(8);

        // a held frame, for the pose sheet (tools/posesheet.mjs)
        if (this.freezeAt !== undefined) { an.time = this.freezeAt; an._prev = null; an.sample(0); } else an.sample(dt);
        const pose = an.pose, b = this.bones;
        for (const j of this.hidden) { const o = j * POSE_STRIDE + 7; pose[o] = pose[o + 1] = pose[o + 2] = 0; }
        { const o = b.pack * POSE_STRIDE + 7; pose[o] = pose[o + 1] = pose[o + 2] = this.pack; }
        // lean (about the side axis) at the spine, bank (about the forward axis) at the hips; a flap and a swing
        rotate(pose, b.spine, 1, 0, 0, -this.lean);
        rotate(pose, b.hips, 0, 0, -1, this.bank);
        rotate(pose, b.flag, 0, 1, 0, Math.sin(this.flap) * 0.18 + this.bank * 0.8);
        rotate(pose, b.hairB, 1, 0, 0, this.tail * 0.6 - this.lean);
        rotate(pose, b.hairB, 0, 0, -1, this.tail * 0.4);
        an.solve();
        // the squash is at the feet: the root's origin is the feet, so scaling it keeps them planted
        const q = this.squash * 0.16;
        this.root.setScale(1 + q * 0.5, 1 + q * 0.5, 1 - q);

        // an idol carrier glows faintly, so everyone can see who has one
        const e = this.emissive, glow = f & FLAG.idol ? 0.25 + 0.15 * Math.sin(performance.now() / 160) : 0;
        e[0] = glow * 1.6; e[1] = glow * 0.5; e[2] = glow * 1.4;
        return step;
    }
}

/** Turn a joint's local rotation by an angle about an axis (in the glTF's Y-up joint frame): q = r · q. */
const r = quat.create(), q0 = quat.create();
function rotate(pose, joint, ax, ay, az, angle) {
    if (!angle || joint < 0) return;
    const o = joint * POSE_STRIDE + 3;
    quat.setAxisAngle(r, [ax, ay, az], angle);
    q0[0] = pose[o]; q0[1] = pose[o + 1]; q0[2] = pose[o + 2]; q0[3] = pose[o + 3];
    quat.multiply(q0, q0, r);
    pose[o] = q0[0]; pose[o + 1] = q0[1]; pose[o + 2] = q0[2]; pose[o + 3] = q0[3];
}
